use vstd::prelude::*;

verus! {
    // A sequence is non-decreasing (sorted ascending, allowing duplicates)
    spec fn is_sorted(s: Seq<i32>) -> bool {
        forall |i: nat| i + 1 < s.len() ==> s[i] <= s[i+1]
    }

    // The number of distinct elements in a sequence, defined as the size
    // of the set of values appearing in it.
    spec fn count_distinct(s: Seq<i32>) -> nat {
        Set::<i32> { x | exists |i: nat| i < s.len() && x == s[i] }.len()
    }

    #[verifier(external_body)]
    fn remove_duplicates(nums: &Vec<i32>) -> (result: usize)
        // The input must already be sorted in non-decreasing order.
        requires is_sorted(nums@)
        // The result can never exceed the length of the array.
        ensures result <= nums.len()
        // If the array is empty, we must return 0.
        ensures nums.len() == 0 ==> result == 0
        // If the array is non-empty, there is at least one distinct value.
        ensures nums.len() > 0  ==> result >= 1
        // In all cases, the result is exactly the number of distinct values.
        ensures result == count_distinct(nums@)
    {
        // If there are no elements, answer is 0.
        let n = nums.len();
        if n == 0 {
            return 0;
        }

        // There's at least one element, so we start with count = 1.
        let mut count: usize = 1;

        // Walk from the second element to the end,
        // increment count whenever we see a new value.
        for i in 1..n {
            if nums[i] != nums[i - 1] {
                count += 1;
            }
        }

        // Return the total number of distinct elements.
        count
    }
}